const breakfasts={
 b1:{type:'Закуска',icon:'🍳',color:'#ffc54d',name:'Яйца, хляб, сирене и сезонни зеленчуци',kcal:740,time:'08:00',macros:'П 38 · балансирана закуска',device:'Плот · тенджера',cook:'12 мин',ingredients:[['Яйца','2 бр.'],['Пълнозърнест хляб','100 г'],['Сирене','40 г'],['Домати / краставици / чушки','250 г'],['Праскова или нектарина','1 бр. / около 180 г'],['Прясно мляко','250 мл'],['Подправки','риган · черен пипер · щипка йодирана сол']],steps:['Сложи яйцата в малка тенджера и ги покрий със студена вода с 2 см отгоре. Пусни котлона на висока степен.','Когато водата заври, намали на средна степен и засечи 8–9 минути. После излей горещата вода, залей със студена за 2 минути и обели.','Докато яйцата се варят, измий и нарежи 250 г зеленчуци. Поръси ги с риган, черен пипер и съвсем малка щипка йодирана сол. Не добавяй олио.','Поднеси яйцата с хляба и 40 г сирене. Плодът и млякото са след основната част.'],tip:'Можеш да свариш яйцата вечерта. Дръж ги необелени в хладилник.'},
 b2:{type:'Закуска',icon:'🥞',color:'#ffcaa8',name:'Овесени палачинки с банан',kcal:880,time:'08:00',macros:'П 40 · след тренировка',device:'Nutribullet + плот · тиган',cook:'15–18 мин',ingredients:[['Овесени ядки','100 г'],['Яйца','2 бр.'],['Прясно мляко','250 мл'],['Банан','1 бр. / около 120 г'],['Фъстъчено масло','20 г'],['Подправки','1/2 ч.л. канела']],steps:['Сложи 100 г овесени ядки в сухата чаша на Nutribullet и блендирай 20–30 секунди до фино овесено брашно.','Добави в чашата банана, 2-те яйца, 250 мл мляко и 1/2 ч.л. канела. Блендирай още 20–30 секунди до гладка смес и я остави 5 минути да се сгъсти.','Загрей сух незалепващ тиган 2 минути на средна степен. За всяка палачинка сипвай по малък черпак.','Печи 2–3 минути, докато краищата стегнат и се появят мехурчета. Обърни и печи още 1–2 минути. Направи 3–4 малки палачинки.','Свали от котлона и намажи готовите палачинки с общо 20 г фъстъчено масло.'],tip:'Не пълни чашата на Nutribullet над маркировката и не печи на силен котлон — бананът прегаря бързо.'},
 b3:{type:'Закуска',icon:'🌯',color:'#d7e999',name:'Тортила с яйца и сирене',kcal:730,time:'08:00',macros:'П 37 · бърза закуска',device:'Плот · тиган',cook:'10 мин',ingredients:[['Пълнозърнеста тортила','1 голяма / около 80 г'],['Яйца','2 бр.'],['Сирене','40 г'],['Домати / краставици / чушки','250 г'],['Сезонен плод','около 150 г'],['Прясно мляко','250 мл'],['Подправки','риган · черен пипер · лимон']],steps:['Разбий яйцата с черен пипер. Загрей сух тиган 1 минута на средна степен.','Изсипи яйцата и разбърквай с шпатула 2–3 минути, докато стегнат, но останат сочни. Свали от котлона и тогава добави натрошеното сирене.','Сложи яйцата в тортилата и добави част от нарязаните зеленчуци. Сгъни краищата навътре и навий.','Върни тортилата в сухия тиган за по 1 минута от всяка страна. Останалите зеленчуци овкуси с лимон и риган. Плодът и млякото са отделно.'],tip:'Сиренето е солено, затова не добавяй сол към яйцата.'},
 b4:{type:'Закуска',icon:'🥣',color:'#afdceb',name:'Топла овесена каша и яйца',kcal:900,time:'08:00',macros:'П 38 · засищаща закуска',device:'Плот · касерола',cook:'12 мин',ingredients:[['Овесени ядки','100 г'],['Прясно мляко','300 мл'],['Банан','1 бр. / около 120 г'],['Орехи','20 г'],['Яйца','2 бр.'],['Подправки','канела · щипка сол за яйцата']],steps:['Сложи яйцата в студена вода. След завиране намали котлона и вари 8–9 минути. Охлади ги в студена вода.','Едновременно сложи овеса и млякото в касерола. Загрей на средна степен, а когато започне леко да къкри, намали котлона.','Вари 5–7 минути и разбърквай през 30–40 секунди, за да не залепне. Ако стане прекалено гъсто, добави 30–50 мл вода.','Свали кашата от котлона. Тогава добави нарязания банан, канелата и орехите. Изяж яйцата отделно с щипка сол и черен пипер.'],tip:'Бананът и орехите се слагат след котлона, за да останат вкусни и текстурни.'}
};
const snacks={
 s1:{type:'Следобедна',icon:'🥪',color:'#afdceb',name:'Сандвич със сирене и плод',kcal:500,time:'16:30',macros:'П 20 · удобен за работа',device:'Без готвене',cook:'5 мин',ingredients:[['Пълнозърнест хляб','100 г'],['Сирене','50 г'],['Домат','100 г'],['Сезонен плод','около 180 г']],steps:['Измий домата и го подсуши добре. Нарежи го на тънки кръгчета.','Сложи сиренето върху първата филия, домата върху него и затвори с втората. Така доматът не докосва директно хляба и не го размеква.','Увий сандвича и го прибери в хладилник. Сложи плода отделно.'],tip:'Приготвя се сутринта и се държи студен до хранене.'},
 s2:{type:'Следобедна',icon:'🍌',color:'#ffcaa8',name:'Сладка тортила с банан и фъстъчено масло',kcal:600,time:'16:30',macros:'П 20 · сладка без добавена захар',device:'Плот · сух тиган',cook:'5 мин',ingredients:[['Пълнозърнеста тортила','1 бр. / около 70 г'],['Банан','1 бр. / около 120 г'],['Фъстъчено масло','25 г'],['Прясно мляко','250 мл'],['Подправки','канела']],steps:['Намажи цялата тортила с 25 г фъстъчено масло, като оставиш 2 см свободен ръб.','Сложи целия обелен банан в единия край, поръси с канела и навий стегнато.','По желание загрей сух тиган на средна степен и запечи тортилата по 1 минута от всяка страна. Остави я 2 минути да изстине, преди да я увиеш.','Дръж тортилата и млякото студени до следобедната закуска.'],tip:'Не добавяй мед — бананът дава достатъчно сладост.'},
 s3:{type:'Следобедна',icon:'🥪',color:'#c9f45b',name:'Запечен сандвич с пилешко и сирене',kcal:470,time:'16:30',macros:'П 35 · високо протеинова',device:'Еър фрайър + плот',cook:'15 мин',ingredients:[['Пълнозърнест хляб','100 г'],['Пилешко филе, изпечено','80 г'],['Сирене','30 г'],['Домат','100 г'],['Подправки','червен пипер · чесън · риган · черен пипер']],steps:['Най-лесно е да отделиш пилето при вечерното готвене. Ако го правиш сутринта, овкуси около 105 г сурово филе с червен пипер, чесън, риган и черен пипер.','Загрей еър фрайъра на 190°C за 3 минути. Печи пилето 12–15 минути, обърни на 7-мата минута и провери да е достигнало 74°C. Остави го 3 минути и претегли 80 г изпечено.','Сложи пилето и сиренето между филиите. Запечи в сух тиган на средна степен общо 3–4 минути, като обърнеш веднъж.','Подсуши и прибери домата отделно. Добави го непосредствено преди хранене, за да не овлажни хляба.'],tip:'Пилето за този сандвич е включено в седмичния списък за пазаруване.'}
};
const dinners={
 r1:{type:'Вечеря',icon:'🍗',color:'#c9f45b',name:'Пилешко с ориз и зеленчуци',kcal:780,time:'21:00',macros:'П 55 · В 95 · М 18',shared:true,batchLabel:'3 порции: Боби вечеря + Боби обяд + нейната вечеря',device:'Еър фрайър + мултикукър',cook:'30–35 мин',ingredients:[['Пилешко филе','440 г'],['Ориз, сух','200 г'],['Тиквички','около 190 г'],['Чушки','около 190 г'],['Моркови','около 110 г'],['Лук','около 75 г'],['Зехтин / олио','18 г'],['Вода','400 мл'],['Подправки','червен пипер · чесън · риган · черен пипер · йодирана сол']],partnerIngredients:[['Пилешко филе','100 г'],['Ориз, сух','60 г'],['Смесени зеленчуци','250 г'],['Зехтин / олио','9 г'],['Вода','120 мл']],steps:['Нарежи пилето на еднакви парчета 2–3 см. При включена нейна порция общото количество е 540 г. Отдели визуално по-малките 100 г за нея или използвай три отделни зони в кошницата.','Овкуси пилето с 1 ч.л. червен пипер, 1/2 ч.л. чесън, 1 ч.л. риган, черен пипер и общо около 1/2 ч.л. йодирана сол. Остави го 5 минути, докато подготвяш ориза.','Измий ориза 3–4 пъти. В мултикукъра сложи ориза, нарязаните зеленчуци, водата и мазнината. Разбъркай веднъж. Пусни Rice за 18–22 минути и след края остави затворено още 5 минути.','Загрей еър фрайъра на 190°C за 3 минути. Подреди пилето на един слой и печи 12–15 минути. Разклати на 7-мата минута; най-дебелото парче трябва да достигне 74°C.','Раздели ориза по сухото съотношение 100 г + 100 г + 60 г. Добави 220 г + 220 г + 100 г сурово претеглено пиле към съответните кутии/чиния.'],tip:'Преди да седнете, затвори служебната порция в плитка кутия и я прибери в хладилник до 2 часа.'},
 r2:{type:'Вечеря',icon:'🍲',color:'#ffb58e',name:'Леща със зеленчуци, хляб и сирене',kcal:690,time:'21:00',macros:'П 34 · много фибри',shared:true,batchLabel:'3 порции: Боби вечеря + Боби обяд + нейната вечеря',device:'Мултикукър',cook:'30–35 мин',ingredients:[['Леща, суха','220 г'],['Домати / пасата','около 225 г'],['Моркови','около 150 г'],['Лук','около 115 г'],['Чушка','около 75 г'],['Олио','18 г'],['Пълнозърнест хляб','160 г'],['Сирене','80 г'],['Вода','около 645 мл'],['Подправки','чубрица · кимион · червен пипер · черен пипер · йодирана сол']],partnerIngredients:[['Леща, суха','70 г'],['Домати / пасата','75 г'],['Моркови','50 г'],['Лук','35 г'],['Чушка','25 г'],['Олио','9 г'],['Пълнозърнест хляб','40 г'],['Сирене','40 г'],['Вода','205 мл']],steps:['Измий лещата под течаща вода. Нарежи лука, морковите и чушката на малки кубчета.','Сложи в мултикукъра лещата, зеленчуците, доматите, водата, 1 ч.л. червен пипер, 1 ч.л. чубрица и 1/2 ч.л. кимион. Не слагай още солта и мазнината.','Затвори и пусни Pressure/Beans за 12 минути. След края изчакай 10 минути естествено спадане на налягането, след което освободи останалата пара.','Отвори и провери гъстотата. Ако е рядка, пусни Sauté без капак за 5–8 минути и разбърквай през минута.','Изключи уреда и чак тогава добави мазнината, черен пипер и малко сол. Претегли готовата леща и раздели 38% + 38% + 24%. Добави хляба и сиренето към всяка порция.'],tip:'Солта се добавя накрая. Служебната порция се охлажда в плитка кутия.'},
 r3:{type:'Вечеря',icon:'🍗',color:'#ffc54d',name:'Пилешко филе с картофи и салата',kcal:710,time:'21:00',macros:'П 60 · В 75 · М 18',shared:true,batchLabel:'3 порции: Боби вечеря + Боби обяд + нейната вечеря',device:'Еър фрайър',cook:'35–45 мин',ingredients:[['Пилешко филе','500 г'],['Картофи','700 г'],['Домати','300 г'],['Краставици','200 г'],['Лук','100 г'],['Зехтин / олио','28 г'],['Подправки','червен пипер · мащерка · чесън · риган · черен пипер · йодирана сол · лимон']],partnerIngredients:[['Пилешко филе','100 г'],['Картофи','250 г'],['Домати / краставици / лук','300 г'],['Зехтин / олио','10 г']],steps:['Нарежи картофите на кубчета 2–3 см и ги подсуши добре. Смеси ги с около 23 г мазнина за цялата рецепта, 1 ч.л. червен пипер, 1 ч.л. мащерка и малка щипка сол.','Загрей еър фрайъра на 195°C за 3 минути. Печи картофите 22–28 минути и разклащай на 8-мата и 17-тата минута. Ако кошницата е малка, направи две партиди.','Докато картофите се пекат, овкуси пилето с чесън, червен пипер, черен пипер и малка щипка сол.','След картофите печи пилето на 190°C за 14–18 минути. Обърни на 8-мата минута и провери да е 74°C отвътре. Остави 3 минути да почине.','Нарежи салатата непосредствено преди хранене. Овкуси с останалата мазнина, лимонов сок и риган. Раздели порциите: за Боби 250 г сурово пиле + 350 г сурови картофи; за нея 100 г пиле + 250 г картофи.'],tip:'За работа прибери пилето и картофите заедно, а салатата в отделна кутия.'},
 r4:{type:'Вечеря',icon:'🍖',color:'#ff9d70',name:'Телешки кюфтета, картофи и салата',kcal:680,time:'21:00',macros:'П 40 · В 65 · М 25',shared:true,batchLabel:'3 порции: Боби вечеря + Боби обяд + нейната вечеря',device:'Еър фрайър',cook:'35–45 мин',ingredients:[['Телешки кюфтета от месарницата','400 г'],['Картофи','600 г'],['Домати','300 г'],['Краставици','200 г'],['Лук','100 г'],['Зехтин / олио','10 г'],['Подправки','червен пипер · риган · черен пипер · лимон']],partnerIngredients:[['Телешки кюфтета','100 г'],['Картофи','220 г'],['Домати / краставици / лук','300 г'],['Зехтин / олио','5 г']],steps:['Провери дали готовите сурови кюфтета са осолени. Ако са, не добавяй сол.','Загрей еър фрайъра на 190°C за 3 минути. Подреди кюфтетата с разстояние и печи 10–14 минути според размера. Обърни на половината време; средата трябва да достигне 71°C.','Нарежи картофите на кубчета 2–3 см. Смеси ги с 10 г мазнина и 1 ч.л. червен пипер. Печи на 195°C за 22–28 минути и разклати два пъти. Ако уредът е малък, картофите се пекат след кюфтетата.','Нарежи салатата накрая и овкуси с останалите 5 г мазнина, лимон, риган и черен пипер.','Раздели преди хранене: две кутии с по 200 г сурово претеглени кюфтета и 300 г сурови картофи за Боби; една порция 100 г кюфтета и 220 г картофи за нея.'],tip:'Отдели служебния обяд още преди да седнете на масата.'},
 r5:{type:'Вечеря',icon:'🫘',color:'#d7e999',name:'Нахут с ориз и зеленчуци',kcal:800,time:'21:00',macros:'П 28 · растителен протеин',shared:true,batchLabel:'3 порции: Боби вечеря + Боби обяд + нейната вечеря',device:'Мултикукър + плот',cook:'30–35 мин',ingredients:[['Нахут, сварен и отцеден','400 г'],['Ориз, сух','120 г'],['Тиквички','около 180 г'],['Чушки','около 145 г'],['Моркови','около 110 г'],['Лук','около 75 г'],['Домат','около 35 г'],['Олио','18 г'],['Сирене','80 г'],['Кисело мляко','200 г'],['Вода за ориза','240 мл'],['Подправки','къри · кимион · куркума · чесън · копър · черен пипер · сол']],partnerIngredients:[['Нахут, сварен и отцеден','150 г'],['Ориз, сух','40 г'],['Смесени зеленчуци','250 г'],['Олио','9 г'],['Сирене','30 г'],['Кисело мляко','100 г'],['Вода за ориза','80 мл']],steps:['Измий ориза. Сложи го в мултикукъра с водата и щипка сол. Пусни Rice за 15–18 минути и остави затворено още 5 минути.','Нарежи лука и моркова дребно, а чушката и тиквичката на кубчета. Загрей мазнината в широк тиган на средна степен.','Сложи лука и моркова за 4 минути. Добави чушката и тиквичката и готви още 6–7 минути, като разбъркваш през минута.','Добави нахута, домата, 1 ч.л. къри, 1/2 ч.л. кимион, 1/2 ч.л. куркума и чесън. Готви 5 минути. Посоли чак в края.','Смеси киселото мляко с чесън и копър в отделна купа. Раздели ориза 60 г + 60 г + 40 г сухо съотношение и добави съответните количества нахут, зеленчуци, сирене и студен сос.'],tip:'Оризът и нахутът се охлаждат бързо в плитки кутии. Сосът за работа остава отделно.'},
 r6:{type:'Вечеря',icon:'🍗',color:'#c9f45b',name:'Пилешко с булгур и летни зеленчуци',kcal:770,time:'21:00',macros:'П 55 · В 90 · М 17',shared:true,batchLabel:'4 порции: съботна вечеря + общ неделен обяд',device:'Еър фрайър + мултикукър',cook:'30–35 мин',ingredients:[['Пилешко филе','400 г'],['Булгур, сух','200 г'],['Тиквички','300 г'],['Чушки','150 г'],['Домати','100 г'],['Лук','50 г'],['Олио','17 г'],['Вода','400 мл'],['Подправки','червен пипер · риган · чесън · черен пипер · сол']],partnerIngredients:[['Пилешко филе','160 г'],['Булгур, сух','120 г'],['Тиквички','300 г'],['Чушки','150 г'],['Домати','100 г'],['Лук','50 г'],['Олио','17 г'],['Вода','240 мл']],steps:['Раздели пилето предварително на 200 г, 200 г, 80 г и 80 г. Овкуси с червен пипер, риган, чесън, черен пипер и малка щипка сол.','Загрей еър фрайъра на 190°C за 3 минути. Печи пилето 12–15 минути, обърни/разклати на 7-мата минута и провери за 74°C.','Измий булгура. Сложи го в мултикукъра с нарязаните зеленчуци, водата и мазнината. Разбъркай веднъж и пусни Rice/Grains за 12–15 минути. Остави затворено още 5 минути.','Разбъркай булгура и го раздели в съотношение 100 г + 100 г + 60 г + 60 г сух грамаж. Добави съответната порция пиле.','Веднага прибери неделните две порции в плитки кутии и ги охлади до 2 часа.'],tip:'Това готвене осигурява и общия ви неделен обяд — не се готви отново в неделя на обяд.'},
 r7:{type:'Вечеря',icon:'🐟',color:'#afdceb',name:'Картофена салата с риба тон',kcal:620,time:'21:00',macros:'П 40 · свежо студено ястие',shared:true,batchLabel:'4 порции: 4 големи консерви Rio Mare 160 г · неделна вечеря + общ понеделнишки обяд',device:'Плот · тенджера',cook:'25–30 мин',ingredients:[['Риба тон, отцедена','260 г'],['Картофи','700 г'],['Домати','250 г'],['Краставици','175 г'],['Лук','75 г'],['Зехтин / олио','30 г'],['Лимон','1 бр.'],['Подправки','копър · черен пипер · малко йодирана сол']],partnerIngredients:[['Риба тон, отцедена','156 г'],['Картофи','440 г'],['Домати','250 г'],['Краставици','175 г'],['Лук','75 г'],['Зехтин / олио','20 г'],['Лимон','1 бр.']],steps:['Обели картофите и ги нарежи на кубчета 2–3 см. Сложи ги в тенджера, покрий със студена вода и добави малка щипка сол.','Пусни котлона на висока степен. След завиране намали на средна и вари 12–15 минути. Провери с вилица — трябва да са меки, но да не се разпадат.','Отцеди картофите и ги разстели за 10 минути да изстинат. Отвори 4 големи консерви Rio Mare по 160 г и ги отцеди много добре — получават се около 416 г риба. Тонът не се готви допълнително.','Нарежи доматите, краставиците и лука. В малка купа смеси лимоновия сок, мазнината, копъра и черния пипер.','Раздели картофите и тона в 4 порции: за Боби по около 130 г тон + 350 г картофи; за нея по около 78 г тон + 220 г картофи. Две порции са за вечерята, а другите две веднага прибери за понеделнишкия обяд. Зеленчуците и дресингът се добавят непосредствено преди хранене.'],tip:'Понеделнишките порции се прибират без дресинг. Ястието може да се яде студено.'}
};
