dinners.r3.lunchIngredients=[['Пилешко филе','250 г сурово'],['Картофи','350 г сурови'],['Домати / краставици / лук','300 г общо · отделно'],['Зехтин / олио','14 г'],['Подправки','червен пипер · мащерка · чесън · риган · черен пипер · лимон · малко сол']];
